from google.adk.agents import Agent

def obtener_clima(ciudad: str) -> dict:
    """Devuelve el clima actual de una ciudad."""
    return {"ciudad": ciudad, "clima": "soleado"}

root_agent = Agent(
    name="agente_clima",
    model="gemini-2.0-flash",
    instruction="Usa la herramienta para responder sobre el clima.",
    tools=[obtener_clima],
)
